    oid = shop.orders.handle_create({"customer_id": "c1", "items": [{"sku": "BOOK", "quantity": 1}]}).body["order_id"]
    shop.orders.handle_cancel(oid)
    response = shop.fulfilment.handle_packing_slip(oid)
